// A small sprite for a bag / shop item. The files live in public/sprites/items
// and are listed in public/data/item-icons.json (generated by
// tools/download-item-sprites.cjs). Items without a sprite render nothing, so a
// newly-added item degrades gracefully until the downloader is re-run.

import { jsx } from 'react/jsx-runtime'
import { itemIcons } from '../data/gameData.js'

/** @param {{ itemId: string, size?: number, className?: string }} props */
export function ItemIcon({ itemId, size = 20, className }) {
  const file = itemIcons[itemId]
  if (!file) return null
  return jsx('img', {
    className: `item-icon${className ? ` ${className}` : ''}`,
    src: `/sprites/items/${file}`,
    width: size,
    height: size,
    alt: '',
    draggable: false,
  })
}
